<template>
 <main class="people-page" v-loading="loading">
  <header class="page-heading">
   <div class="heading-copy"><span class="page-eyebrow"><el-icon><UserFilled/></el-icon> 团队与访问管理</span><h1>人员管理</h1><p>一处管理人员账号、岗位与负责门店</p></div>
   <div class="heading-side"><div class="people-metrics"><div><strong>{{data.users.length}}</strong><span>人员总数</span></div><div><strong>{{configuredCount}}</strong><span>已配置</span></div><div><strong>{{pendingCount}}</strong><span>微信待处理</span></div></div><el-button class="create-person" type="primary" size="large" :icon="Plus" :disabled="!auth.isAdmin||loading" :title="!auth.isAdmin?'新增及岗位分配由管理员维护':''" @click="create">新增人员</el-button></div>
  </header>
  <el-alert v-if="loadError" :title="loadError" type="error" :closable="false"><template #default><el-button text @click="load">重新加载</el-button></template></el-alert>
  <section class="directory-card"><el-tabs v-model="pageTab" class="directory-tabs"><el-tab-pane name="people"><template #label><span class="tab-label"><el-icon><User/></el-icon>人员列表<span class="tab-count">{{data.users.length}}</span></span></template></el-tab-pane><el-tab-pane name="bindings"><template #label><span class="tab-label"><el-icon><ChatDotRound/></el-icon>微信绑定申请<span v-if="pendingCount" class="tab-count pending">{{pendingCount}}</span></span></template></el-tab-pane></el-tabs>
  <template v-if="pageTab==='people'">
   <el-form class="filters" label-position="top" @submit.prevent="query">
    <el-form-item label="查找人员" class="search-field"><el-input v-model="draft.q" :prefix-icon="Search" clearable placeholder="姓名、账号或手机号" aria-label="搜索人员" @keyup.enter="query"/></el-form-item>
    <el-form-item label="岗位"><el-select v-model="draft.role" clearable filterable placeholder="全部岗位" aria-label="筛选岗位"><el-option v-for="p in data.positions" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item>
    <el-form-item label="负责范围"><StoreRegionSelect v-model="draft.stores" :stores="data.stores" multiple restrict-to-stores placeholder="全部门店 / 区域" input-width="100%"/></el-form-item>
    <el-form-item label="登录端"><el-select v-model="draft.channel" aria-label="筛选登录端"><el-option label="全部登录端" value="all"/><el-option label="可登录网页" value="web"/><el-option label="可登录小程序" value="mini"/><el-option label="双端登录" value="both"/></el-select></el-form-item>
    <el-form-item label="配置状态"><el-select v-model="draft.state" aria-label="筛选配置状态"><el-option label="全部状态" value="all"/><el-option label="已配置" value="ready"/><el-option label="待核对" value="legacy"/></el-select></el-form-item>
    <div class="filter-actions"><el-button type="primary" plain native-type="submit" :icon="Search">查询</el-button><el-button @click="reset">重置</el-button></div>
   </el-form>
   <div class="list-tools"><div class="list-caption"><h2>人员目录</h2><span>共 <b>{{filtered.length}}</b> 位人员</span><span v-if="filtersChanged" class="filter-pending">筛选已修改，点击查询应用</span></div><div class="list-actions"><el-button v-if="auth.isAdmin" text :icon="OfficeBuilding" @click="reverseOpen=true">按门店查人员</el-button><el-button text :icon="Refresh" :loading="loading" @click="load">刷新</el-button></div></div>
   <el-alert v-if="createdNotice" :title="createdNotice" type="success" show-icon @close="createdNotice=''"/>
   <el-table class="people-table" :data="paged" row-key="id" :row-class-name="({row})=>row.id===highlightId?'new-person':''" empty-text="没有符合条件的人员，可重置筛选查看全部">
    <el-table-column label="人员" min-width="205"><template #default="{row}"><div class="person-cell"><el-avatar class="person-avatar" :size="40" shape="square" :src="row.avatar_url||undefined" :style="avatarStyle(row)">{{avatarLetter(row)}}</el-avatar><div class="person-name"><button class="person-link" @click="openDetail(row)">{{row.display_name||row.username}}</button><div class="account-name">{{row.username}}</div></div></div></template></el-table-column>
    <el-table-column label="档案与归属" min-width="170"><template #default="{row}"><template v-if="employee(row)"><el-button v-if="canOpenStaff" link @click="openStaff(row)">{{employee(row).name}}</el-button><span v-else>{{employee(row).name}}</span><div class="secondary">{{employee(row).store_name||'未登记归属'}} · {{row.employment_status}}</div></template><span v-else class="secondary">未关联员工档案</span></template></el-table-column>
    <el-table-column label="岗位及负责范围" min-width="260"><template #default="{row}"><div v-for="a in assignments(row)" :key="a.position_id" class="assignment-line"><div class="assignment-title"><span class="role-name" :class="{primary:a.is_primary}" :title="a.is_primary?'主岗位':'兼任岗位'"><span class="role-description">{{a.is_primary?'主岗位：':'兼任岗位：'}}</span>{{position(a.position_id)?.name||'未分配岗位'}}</span></div><button class="scope-link" @click="showScope(row,a)">{{compactScope(a)}}</button></div><span v-if="!assignments(row).length" class="secondary">未分配岗位</span></template></el-table-column>
    <el-table-column label="登录端" width="110"><template #default="{row}"><div class="channel-list"><span v-for="c in channels(row)" :key="c" class="channel-chip" :class="c"><el-icon><Monitor v-if="c==='web'"/><Cellphone v-else/></el-icon>{{channelLabel(c)}}</span></div></template></el-table-column>
    <el-table-column label="微信绑定" width="100"><template #default="{row}"><span class="binding-state" :class="{'is-bound':bound(row)}"><el-icon v-if="bound(row)"><CircleCheck/></el-icon>{{bound(row)?'已绑定':'未绑定'}}</span></template></el-table-column>
    <el-table-column label="配置状态" width="100"><template #default="{row}"><span class="config-state" :class="{'needs-review':!ready(row)}"><i aria-hidden="true"/>{{ready(row)?'已配置':'待核对'}}</span></template></el-table-column>
    <el-table-column label="操作" width="160" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDetail(row)">查看详情</el-button><el-button v-if="auth.isAdmin" link class="assign-action" @click="openDetail(row,'roles')">分配岗位</el-button></template></el-table-column>
   </el-table>
   <div class="directory-footer"><span>按岗位分别配置门店，权限范围清晰可查</span><el-pagination v-model:current-page="page" :page-size="pageSize" :total="filtered.length" background layout="total, prev, pager, next"/></div>
  </template>
  <section v-else class="bindings-panel">
   <div class="list-tools"><div><h2>微信绑定申请</h2><p class="secondary">核对申请编号与本人身份后绑定已有账号。绑定沿用账号现有权限。</p></div><el-button @click="loadBindings">刷新申请</el-button></div>
   <el-radio-group v-model="bindingFilter" class="binding-filter"><el-radio-button value="pending">待处理（{{pendingCount}}）</el-radio-button><el-radio-button value="all">全部记录</el-radio-button></el-radio-group>
   <el-table :data="visibleBindings" empty-text="暂无待处理申请"><el-table-column prop="name" label="申请姓名" min-width="120"/><el-table-column prop="contact" label="联系方式" min-width="140"/><el-table-column prop="verification" label="申请编号" min-width="160"/><el-table-column label="状态" width="110"><template #default="{row}">{{bindingLabels[row.status]||row.status}}</template></el-table-column><el-table-column label="关联人员" min-width="240"><template #default="{row}"><el-select v-if="row.status==='pending'" v-model="bindingTargets[row.id]" filterable placeholder="核实后选择已有人员" :disabled="busyBinding!==null"><el-option v-for="u in data.users" :key="u.id" :value="u.id" :label="(u.display_name||u.username)+'（'+u.username+'）'"/></el-select><el-button v-else-if="personById(row.user_id)" link @click="openDetail(personById(row.user_id))">{{personById(row.user_id).display_name||personById(row.user_id).username}}</el-button><span v-else>{{row.display_name||row.username||'—'}}</span></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><template v-if="row.status==='pending'"><el-button link type="primary" :disabled="!bindingTargets[row.id]||busyBinding!==null" @click="reviewBinding(row,'approve')">批准</el-button><el-button link type="danger" :disabled="busyBinding!==null" @click="reviewBinding(row,'reject')">拒绝</el-button></template><el-button v-if="row.status==='approved'" link type="danger" :disabled="busyBinding!==null" @click="reviewBinding(row,'revoke')">解除绑定</el-button></template></el-table-column></el-table>
  </section>
  </section>

  <el-drawer v-model="detailOpen" size="min(920px,96vw)" :before-close="closeDetail" :close-on-click-modal="false" class="people-detail-drawer">
   <template #header><div v-if="selected" class="detail-heading"><el-avatar :size="54" shape="square" :src="selected.avatar_url||undefined" :style="avatarStyle(selected)">{{avatarLetter(selected)}}</el-avatar><div><span class="detail-eyebrow">人员详情</span><h2>{{selected.display_name||selected.username}}</h2><p class="secondary">{{selected.username}} · {{channels(selected).map(channelLabel).join('、')}}{{employee(selected)?' · '+selected.employment_status:''}}</p></div></div></template>
   <template v-if="selected">
    <el-tabs v-model="detailTab" :before-leave="leaveDetailTab"><el-tab-pane label="账号资料" name="profile"/><el-tab-pane v-if="auth.isAdmin" label="岗位与门店" name="roles"/><el-tab-pane v-if="auth.isAdmin" label="实际权限" name="rights"/><el-tab-pane v-if="auth.isAdmin" label="变更记录" name="history"/></el-tabs>
    <el-alert v-if="detailError" :title="detailError" type="error" :closable="false"/>
    <section v-if="detailTab==='profile'" class="profile-panel">
     <section class="profile-avatar-card">
      <el-avatar :size="88" shape="square" :src="selected.avatar_url||undefined" :style="avatarStyle(selected)">{{avatarLetter(selected)}}</el-avatar>
      <div class="profile-avatar-copy"><h3>个人头像</h3><p>上传照片后，可缩放、拖动裁剪</p><div class="profile-avatar-actions"><el-upload :auto-upload="false" :show-file-list="false" accept="image/png,image/jpeg,image/webp" :disabled="saving" :on-change="file=>chooseAvatar(file.raw)"><el-button type="primary" plain :disabled="saving">{{selected.avatar_url?'更换头像':'上传头像'}}</el-button></el-upload><el-button v-if="selected.avatar_url" text :disabled="saving" @click="removeAvatar">恢复默认</el-button></div><span class="secondary">支持 PNG、JPEG、WebP，原图不超过10MB</span></div>
     </section>
     <el-form ref="profileFormRef" class="profile-form" :model="profileForm" :rules="profileRules" label-position="top" :disabled="saving"><div class="section-heading"><h3>基本资料</h3><p class="secondary">维护账号持有人的姓名与手机号码</p></div><el-form-item label="显示名称" prop="display_name"><el-input v-model.trim="profileForm.display_name" maxlength="30" placeholder="填写姓名或常用名称"/></el-form-item><el-form-item label="手机号" prop="phone"><el-input v-model.trim="profileForm.phone" type="tel" inputmode="numeric" autocomplete="tel-national" maxlength="11" placeholder="填写11位中国大陆手机号"/><span class="field-hint">选填，仅支持手机号码</span></el-form-item><el-form-item label="登录账号" prop="username" class="login-account-field"><el-input v-model.trim="profileForm.username" maxlength="50" autocomplete="off"/><span class="field-hint">用于网页登录，修改后请使用新账号登录</span></el-form-item></el-form>
     <div v-if="employee(selected)" class="profile-employee-link"><div><strong>关联员工档案</strong><p>{{employee(selected).name}} · {{employee(selected).position||'未登记职务'}} · {{employee(selected).store_name||'未登记归属'}}</p></div><el-button v-if="canOpenStaff" text @click="openStaff(selected)">查看档案</el-button></div>
     <div class="account-tools"><div><span>微信登录</span><el-tag :type="bound(selected)?'success':'info'">{{bound(selected)?'已绑定':'未绑定'}}</el-tag></div><el-button @click="goBindings">查看绑定申请</el-button></div>
     <div v-if="channels(selected).includes('web')" class="account-tools"><div><span>网页密码</span><span class="secondary">仅用于网页登录</span></div><el-button @click="passwordOpen=true;passwordForm={password:'',confirm:''}">修改密码</el-button></div>
     <div class="danger-zone"><span class="secondary">{{employee(selected)?'已关联员工档案的账号保留历史身份，离职后自动停用。':'删除账号会影响登录，请核对历史使用情况。'}}</span><el-button type="danger" plain :disabled="selected.id===auth.user?.id||!!employee(selected)" @click="removePerson">删除账号</el-button></div>
    </section>
    <section v-else-if="detailTab==='roles'" class="roles-panel">
     <el-alert v-if="!selected.access" title="此账号沿用旧配置，请逐项核对岗位、登录端和负责范围后保存。" type="warning" :closable="false"/>
     <el-form label-position="top"><el-form-item label="关联员工档案"><el-select v-model="roleForm.employee_id" filterable clearable placeholder="无员工档案账号"><el-option v-for="e in data.employees" :key="e.id" :value="e.id" :disabled="!!e.linked_user_id&&e.linked_user_id!==selected.id" :label="employeeLabel(e)"/></el-select></el-form-item></el-form>
     <PersonnelRoleEditor v-model="roleForm" :data="data" :user-id="selected.id"/>
     <el-button :loading="previewLoading" @click="previewRoles(false)">核对本次实际权限</el-button>
     <div v-if="rolePreview" class="preview-block"><p>本次调整预览，尚未保存</p><div v-for="(result,c) in rolePreview" :key="c"><strong>{{channelLabel(c)}}</strong><p v-for="a in result.assignments" :key="a.position_id" class="secondary">{{a.name}}：{{a.stores.map(s=>s.store_name).join('、')||'此端无可访问门店'}}</p></div></div>
    </section>
    <section v-else-if="detailTab==='rights'" v-loading="reportLoading">
     <el-radio-group v-model="reportChannel"><el-radio-button value="web">网页</el-radio-button><el-radio-button value="mini">小程序</el-radio-button></el-radio-group>
     <el-alert v-if="report.legacy" type="warning" title="旧配置的兼容权限；请在岗位与门店中核对后保存。" :closable="false"/>
     <div class="rights-filter"><el-input v-model="rightQuery" clearable placeholder="搜索功能"/><StoreRegionSelect v-model="rightStore" clearable placeholder="核对某家门店" :stores="data.stores" restrict-to-stores /></div>
     <p v-if="rightStore" class="secondary">按已配置功能列出所选门店的允许 / 拒绝结果；未列出的功能未获授权。</p>
     <el-table :data="visibleRights" empty-text="当前端没有匹配的已授权功能"><el-table-column label="功能" min-width="180"><template #default="{row}">{{permissionLabel(row.code)}}</template></el-table-column><el-table-column v-if="rightStore" label="结果" width="90"><template #default="{row}"><el-tag :type="row.stores.some(s=>s.id===rightStore)?'success':'danger'">{{row.stores.some(s=>s.id===rightStore)?'允许':'拒绝'}}</el-tag></template></el-table-column><el-table-column label="实际可访问门店" min-width="300"><template #default="{row}">{{row.stores.map(s=>s.store_name).join('、')||'无可访问门店'}}</template></el-table-column><el-table-column label="岗位来源" min-width="140"><template #default="{row}">{{rightsSources(row)}}</template></el-table-column></el-table>
    </section>
    <section v-else v-loading="reportLoading"><el-table :data="logs" empty-text="暂无变更记录"><el-table-column label="时间" min-width="155"><template #default="{row}">{{formatTime(row.created_at)}}</template></el-table-column><el-table-column prop="actor_name" label="操作人" width="110"/><el-table-column prop="reason" label="原因" min-width="180"/><el-table-column type="expand"><template #default="{row}"><div class="audit-diff"><strong>调整前</strong><p>{{auditLabel(row.before_json)}}</p><strong>调整后</strong><p>{{auditLabel(row.after_json)}}</p></div></template></el-table-column></el-table></section>
   </template>
   <template #footer><div class="drawer-footer"><el-button :disabled="saving" @click="closeDetail(()=>detailOpen=false)">关闭</el-button><el-button v-if="detailTab==='profile'" type="primary" :loading="saving" @click="saveProfile">保存账号资料</el-button><el-button v-if="detailTab==='roles'" type="primary" :loading="saving" @click="saveRoles">保存岗位与门店</el-button></div></template>
  </el-drawer>

  <el-drawer v-model="creating" class="people-create-drawer" size="min(820px,96vw)" :close-on-click-modal="false" :before-close="closeCreate"><template #header><div><span class="detail-eyebrow">团队成员</span><h2 class="create-title">新增人员</h2><p class="secondary">关联身份、分配岗位，核对后完成开通</p></div></template>
   <el-steps :active="createStep" simple><el-step title="身份与登录"/><el-step title="岗位与门店"/><el-step title="核对创建"/></el-steps>
   <el-alert v-if="createError" :title="createError" type="error" :closable="false"/>
   <el-form v-if="createStep===0" label-position="top" class="create-form">
    <el-form-item label="人员身份" required><el-radio-group v-model="identityType" @change="newForm.employee_id=null"><el-radio value="employee">关联已有员工档案</el-radio><el-radio value="standalone">无员工档案账号</el-radio></el-radio-group></el-form-item>
    <el-form-item v-if="identityType==='employee'" label="员工档案" required><el-select v-model="newForm.employee_id" filterable placeholder="选择尚未关联账号的员工" @change="fillEmployeeName"><el-option v-for="e in data.employees" :key="e.id" :value="e.id" :disabled="!!e.linked_user_id" :label="employeeLabel(e)"/></el-select><p class="secondary">已有账号的员工不重复创建。<router-link v-if="canOpenStaff" to="/staff-management/employees">前往员工管理建档</router-link></p></el-form-item>
    <el-form-item label="显示名称" required><el-input v-model.trim="newForm.display_name" maxlength="30" placeholder="人员姓名或账号显示名称"/></el-form-item>
    <el-form-item label="登录账号" required><el-input v-model.trim="newForm.username" maxlength="50" placeholder="设置唯一登录账号" autocomplete="off"/></el-form-item>
    <el-form-item label="允许登录端" required><el-checkbox-group v-model="newForm.channels"><el-checkbox value="web">网页</el-checkbox><el-checkbox value="mini">小程序</el-checkbox></el-checkbox-group></el-form-item>
    <el-form-item v-if="newForm.channels.includes('web')" label="网页初始密码" required><el-input v-model="newForm.password" type="password" show-password autocomplete="new-password" placeholder="至少6位"/></el-form-item>
   </el-form>
   <PersonnelRoleEditor v-else-if="createStep===1" v-model="newForm" :data="data" class="create-form"/>
   <section v-else class="confirmation"><h3>{{newForm.display_name}}</h3><p>{{newForm.username}} · {{newForm.channels.map(channelLabel).join('、')}}</p><p class="secondary">{{newForm.employee_id?data.employees.find(e=>e.id===newForm.employee_id)?.name+' · 已关联员工档案':'无员工档案账号'}}</p><div v-for="(result,c) in createPreview" :key="c" class="preview-block"><strong>{{channelLabel(c)}}实际范围</strong><p v-for="a in result.assignments" :key="a.position_id">{{a.name}} <span class="secondary">{{a.is_primary?'主岗位':'兼任'}} · {{a.stores.map(s=>s.store_name).join('、')||'此端无可访问门店'}}</span></p><el-collapse v-if="result.permissions.length"><el-collapse-item :title="'查看'+result.permissions.length+'项功能权限'" name="codes"><p v-for="p in result.permissions" :key="p.code" class="secondary">{{permissionLabel(p.code)}}：{{p.stores.map(s=>s.store_name).join('、')||'无可访问门店'}}</p></el-collapse-item></el-collapse></div><p>创建原因：{{newForm.reason}}</p></section>
   <template #footer><div class="drawer-footer"><el-button :disabled="saving" @click="closeCreate(()=>creating=false)">取消</el-button><el-button v-if="createStep>0" :disabled="saving" @click="createStep--;createError=''">上一步</el-button><el-button v-if="createStep<2" type="primary" :loading="previewLoading" @click="nextCreate">下一步</el-button><el-button v-else type="primary" :loading="saving" @click="submitCreate">确认创建</el-button></div></template>
  </el-drawer>
  <AvatarCropDialog v-model="croppingAvatar" :file="avatarFile" :busy="saving" :error="avatarError" @save="saveAvatar"/>
  <el-dialog v-model="passwordOpen" title="修改网页密码" width="min(460px,94vw)" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="新密码" required><el-input v-model="passwordForm.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认新密码" required><el-input v-model="passwordForm.confirm" type="password" show-password autocomplete="new-password"/></el-form-item></el-form><template #footer><el-button @click="passwordOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="savePassword">保存密码</el-button></template></el-dialog>
  <el-dialog v-model="scopeOpen" title="岗位负责门店" width="min(620px,94vw)"><h3>{{scopeTitle}}</h3><p v-for="s in scopeStores" :key="s.id">{{s.store_name}}</p><el-empty v-if="!scopeStores.length" description="无可访问门店" :image-size="60"/></el-dialog>
