async function closeDetail(done){if(!saving.value&&await discard())done()}
async function leaveDetailTab(){if(saving.value)return false;const ok=await discard();if(ok&&dirty.value){const u=selected.value;profileForm.value={username:u.username,display_name:u.display_name,phone:u.phone||'',profile_version:u.profile_version};roleForm.value=roleDraft(u);rolePreview.value=null}detailError.value='';return ok}
function openStaff(u){const e=employee(u);if(e)router.push({path:'/staff-management/employees',query:{employee_name:e.name,employment_status:e.status}})}
function employeeLabel(e){return `${e.name} · ${e.store_name||'未登记归属'} · ${e.position||''}${e.linked_user_id?'（已有账号）':''}`}
async function goBindings(){await closeDetail(()=>{detailOpen.value=false;pageTab.value='bindings';bindingFilter.value='all'})}
const profileFormRef=ref(null)
const profileRules={username:[{required:true,message:'请填写登录账号',trigger:'blur'}],display_name:[{required:true,message:'请填写显示名称',trigger:'blur'}],phone:[{validator:(_rule,value,done)=>{if(value&&!/^1[3-9]\d{9}$/.test(value))done(Error('请输入有效的11位中国大陆手机号'));else done()},trigger:'blur'}]}
async function saveProfile(){if(saving.value)return;try{await profileFormRef.value?.validate()}catch{return}if(saving.value)return;detailError.value='';saving.value=true;try{if(auth.isAdmin)await api.profile(selectedId.value,profileForm.value);else{const {profile_version,...payload}=profileForm.value;await updateUser(selectedId.value,payload)}if(!await load()){detailError.value='账号资料已保存，列表刷新失败，请重新加载';return}await openDetail(personById(selectedId.value),'profile');ElMessage.success('账号资料已保存')}catch(e){detailError.value=e.message}finally{saving.value=false}}
async function saveRoles(){if(saving.value)return;if(!roleForm.value.reason.trim()){detailError.value='请填写调整原因';return}detailError.value='';saving.value=true;try{await api.save(selectedId.value,{...roleForm.value,review_fingerprint:roleFingerprint.value||undefined});if(!await load()){detailError.value='岗位配置已保存，列表刷新失败，请重新加载';return}await openDetail(personById(selectedId.value),'roles');ElMessage.success('岗位与门店已保存')}catch(e){detailError.value=e.message}finally{saving.value=false}}
const previewLoading=ref(false)
async function previewRoles(isNew){previewLoading.value=true;try{const f=isNew?newForm.value:roleForm.value;const r=await api.preview({...f,user_id:isNew?0:selectedId.value,password:undefined});if(isNew){createPreview.value=r.preview;createFingerprint.value=r.review_fingerprint}else{rolePreview.value=r.preview;roleFingerprint.value=r.review_fingerprint}return true}catch(e){if(isNew)createError.value=e.message;else detailError.value=e.message;return false}finally{previewLoading.value=false}}
