function showScope(u,a){scopeTitle.value=(u.display_name||u.username)+' · '+(position(a.position_id)?.name||'岗位');scopeStores.value=actualStores(a);scopeOpen.value=true}
const creating=ref(false),createStep=ref(0),createError=ref(''),identityType=ref('employee'),newForm=ref({}),createPreview=ref(null)
function create(){identityType.value=data.employees.length?'employee':'standalone';newForm.value={display_name:'',username:'',password:'',employee_id:null,channels:[],assignments:[{position_id:null,is_primary:true,mode:'stores',store_ids:[],region_ids:[]}],reason:'',version:0};createStep.value=0;createError.value='';createPreview.value=null;creating.value=true}
async function closeCreate(done){if(saving.value||previewLoading.value)return;try{if(newForm.value.username||newForm.value.display_name||createStep.value)await ElMessageBox.confirm('确认放弃本次新增？','取消新增',{type:'warning'});newForm.value.password='';done()}catch{}}
