function chooseAvatar(file){if(!file||saving.value)return;avatarFile.value=file;avatarError.value='';croppingAvatar.value=true}
async function refreshAvatar(avatarUrl){
 const baseline=JSON.parse(profileInitial.value)
 if(selected.value)selected.value.avatar_url=avatarUrl
 if(selectedId.value===auth.user?.id)auth.user.avatar_url=avatarUrl
 if(!await load()){ElMessage.warning('头像已保存，列表刷新失败，请重新加载');return}
 const fresh=selected.value
 if(fresh&&['username','display_name','phone'].every(k=>(fresh[k]||'')===(baseline[k]||''))){profileForm.value.profile_version=fresh.profile_version;baseline.profile_version=fresh.profile_version;profileInitial.value=JSON.stringify(baseline)}
 else ElMessage.warning('头像已保存，但账号资料被其他人修改。请保留草稿并重新核对资料。')
}
